{#- The first paginator page only redirects to its section, so leave it out -#}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink is not ending_with(pat="/page/1/") %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
